  "source": "def investigate(context, acquire):
    events = context.get('events')
    if events is None:
        events = []
    count = 0
    status = 'open'
    pending = []
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = event.get('bytes')
            if data is None:
                data = []
            if status == 'open':
                seq = pending + list(data)
                pending = []
                pos = 0
                n = len(seq)
                while pos < n:
                    b = seq[pos]
                    if b < 128:
                        count += 1
                        pos += 1
                    elif b < 192:
                        status = 'error'
                        break
                    elif b < 224:
                        need = 1
                        low = 128
                        high = 191
                    elif b < 240:
                        need = 2
                        low = 128
                        high = 191
                        if b == 224:
                            low = 160
                        elif b == 237:
                            high = 159
                    elif b < 248:
                        need = 3
                        low = 128
                        high = 191
                        if b == 240:
                            low = 144
                        elif b == 244:
                            high = 143
                    else:
                        status = 'error'
                        break
                    if pos + need + 1 > n:
                        pending = seq[pos:]
                        pos = n
                        break
                    ok = True
                    for j in range(1, need + 1):
                        c = seq[pos + j]
                        if c < low or c > high:
                            ok = False
                            break
                    if not ok:
                        status = 'error'
                        break
                    count += 1
                    pos += need + 1
        elif op == 'finish':
            if status == 'open':
                if len(pending) == 0:
                    status = 'finished'
                else:
                    status = 'error'
                pending = []
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}
